// Metal Shading Language (as generated by Unity's HLSLcc) -> GLSL ES 3.20.
//
// Conventions the GLES Metal emulation relies on:
//   * Constant buffers become raw `uvec4[]` uniform blocks named <stage>_<param> holding the buffer bytes exactly as
//     Metal lays them out; members are read through generated accessors, so half/float/bool packing matches.
//   * Every (texture, sampler) pair used by the shader becomes one sampler uniform; read()/get_width() use a pair
//     with sampler == -1.
//   * Vertex inputs keep their [[attribute(n)]] as layout(location = n). Varyings are named v_<user tag>.
//   * The vertex shader negates gl_Position.y so GL framebuffer rows match Metal texture rows (row 0 = top), and,
//     unless clip_control is available, remaps Metal's [0,1] clip-space depth to GL's [-1,1].
#pragma once

#include <string>
#include <utility>
#include <vector>

namespace msl {

enum class TexKind { Tex2D, Tex2DArray, Tex3D, TexCube, TexCubeArray, Depth2D, Depth2DArray, DepthCube };

struct SamplerUse {
    std::string uniform;   // GLSL sampler uniform name
    int texture = 0;       // Metal [[texture(n)]]
    int sampler = -1;      // Metal [[sampler(n)]], -1 for read()/size queries
    TexKind kind = TexKind::Tex2D;
    bool compare = false;  // sampled through sample_compare (shadow sampler)
};

struct BlockUse {
    std::string block;     // GLSL uniform block name
    int buffer = 0;        // Metal [[buffer(n)]]
    int size = 0;          // bytes the shader reads (multiple of 16)
};

struct VertexInput {
    std::string name;
    int location = 0;
    int components = 4;
    char base = 'f';       // 'f' float/half, 'i' int, 'u' uint
};

struct Shader {
    bool ok = false;
    bool vertex = false;
    std::string error;
    std::string glsl;
    std::vector<BlockUse> blocks;
    std::vector<SamplerUse> samplers;
    std::vector<VertexInput> inputs;
    std::vector<int> color_outputs;   // fragment [[color(n)]] locations written
};

// macros: the MTLCompileOptions preprocessor macros (name, value). clip_control: GL_EXT_clip_control is in use, so
// clip-space depth stays [0,1].
// entry: the function to translate (MTLFunction name); empty = the first vertex/fragment function.
Shader translate(const std::string& source, const std::vector<std::pair<std::string, std::string>>& macros, bool clip_control,
                 const std::string& entry = "");

}  // namespace msl
